L33_1 = "\235\170\184\236\157\180 \236\158\145\236\149\132\236\167\132 \237\131\147\236\151\144 \234\178\128\236\157\132 \236\165\144\235\138\148 \234\178\140 \236\157\181\236\136\153\237\149\152\236\167\136 \236\149\138\236\149\152\236\130\172\236\152\168\235\141\176... \234\183\184\235\140\128, \236\152\164\235\165\180\236\185\180\236\153\128\236\157\152 \235\140\128\235\160\168\236\157\180 \235\167\142\236\157\128 \235\143\132\236\155\128\236\157\180 \235\144\169\235\139\136\235\139\164."
L32_1.m_Talk_KOREA = L33_1
