L33_1 = "\228\189\147\227\129\140\229\176\143\227\129\149\227\129\143\227\129\170\227\129\163\227\129\159\227\129\155\227\129\132\227\129\167\229\137\163\227\129\174\233\135\141\227\129\149\227\129\171\230\133\163\227\130\140\227\129\170\227\129\139\227\129\163\227\129\159\227\129\174\227\129\167\227\129\153\227\129\140\226\128\166\226\128\166\227\130\170\227\131\171\227\130\171\227\129\168\227\129\174\230\137\139\229\144\136\227\130\143\227\129\155\227\129\167\227\129\160\227\129\132\227\129\182\230\133\163\227\130\140\227\129\166\227\129\141\227\129\190\227\129\151\227\129\159\227\128\130"
